import app from 'flarum/forum/app';
import FormModal from 'flarum/common/components/FormModal';
import Button from 'flarum/common/components/Button';
import Avatar from 'flarum/common/components/Avatar';
import LoadingIndicator from 'flarum/common/components/LoadingIndicator';
import Stream from 'flarum/common/utils/Stream';
import extractText from 'flarum/common/utils/extractText';
import username from 'flarum/common/helpers/username';
import useStyles from '../styles';
import { setTeam } from './BuildTeam';
import { t } from '../util';
const MAX_ROLE = 60;

/**
 * The owner's (or a moderator's) team window: who is on the build's team and
 * who is invited, their roles, and a form to invite someone else by name.
 */
export default class TeamModal extends FormModal {
  oninit(vnode) {
    super.oninit(vnode);
    useStyles();
    this.members = null;
    this.query = Stream('');
    this.role = Stream('');
    this.results = [];
    this.picked = null;
    app.store.find('garage-members', {
      filter: {
        build: this.attrs.build.id()
      },
      include: 'user'
    }).then(members => {
      this.members = members;
      m.redraw();
    });
  }
  className() {
    return 'GarageTeamModal Modal--small';
  }
  title() {
    return t('team.manage_title');
  }
  content() {
    return m("div", {
      className: "Modal-body"
    }, m("div", {
      className: "Form"
    }, this.inviteForm(), this.members ? this.list() : m(LoadingIndicator, {
      display: "block"
    })));
  }
  inviteForm() {
    return m("fieldset", {
      className: "GarageTeamModal-invite"
    }, m("legend", null, t('team.invite_heading')), m("div", {
      className: "Form-group"
    }, m("label", {
      for: "garage-team-user"
    }, t('team.member_label')), m("input", {
      id: "garage-team-user",
      className: "FormControl",
      autocomplete: "off",
      autocapitalize: "none",
      autocorrect: "off",
      spellcheck: false,
      placeholder: extractText(t('team.member_placeholder')),
      value: this.picked ? this.picked.username() : this.query(),
      oninput: e => this.search(e.target.value)
    }), this.results.length && !this.picked ? m("ul", {
      className: "GarageTeamModal-results",
      role: "listbox"
    }, this.results.map(user => m("li", {
      role: "option"
    }, m("button", {
      type: "button",
      onpointerdown: e => {
        e.preventDefault();
        this.pick(user);
      },
      onclick: () => this.pick(user)
    }, m(Avatar, {
      user: user
    }), " ", username(user))))) : null), m("div", {
      className: "Form-group"
    }, m("label", {
      for: "garage-team-role"
    }, t('team.role_label')), m("input", {
      id: "garage-team-role",
      className: "FormControl",
      maxlength: MAX_ROLE,
      placeholder: extractText(t('team.role_placeholder')),
      bidi: this.role,
      onfocus: () => this.results = []
    })), m(Button, {
      type: "submit",
      className: "Button Button--primary",
      loading: this.loading,
      disabled: !this.picked && !this.query().trim()
    }, t('team.invite')));
  }
  list() {
    const members = this.members || [];
    if (!members.length) return m("p", {
      className: "GarageTeamModal-empty"
    }, t('team.empty'));
    return m("ul", {
      className: "GarageTeamModal-list"
    }, members.map(member => m("li", {
      key: member.id(),
      className: "GarageTeamModal-member"
    }, m(Avatar, {
      user: member.user()
    }), m("div", {
      className: "GarageTeamModal-who"
    }, m("span", {
      className: "GarageTeamModal-name"
    }, username(member.user()), member.accepted() ? null : m("span", {
      className: "GarageTeamModal-pending"
    }, t('team.invited'))), m("input", {
      className: "FormControl",
      "aria-label": extractText(t('team.role_for', {
        username: member.user()?.displayName()
      })),
      maxlength: MAX_ROLE,
      placeholder: extractText(t('team.role_placeholder')),
      value: member.role() || '',
      disabled: !member.canEdit(),
      onchange: e => this.saveRole(member, e.target.value)
    })), member.canDelete() ? m(Button, {
      className: "Button Button--icon Button--link",
      icon: "fas fa-times",
      "aria-label": extractText(t(member.accepted() ? 'team.remove' : 'team.withdraw', {
        username: member.user()?.displayName()
      })),
      title: extractText(t(member.accepted() ? 'team.remove' : 'team.withdraw', {
        username: member.user()?.displayName()
      })),
      onclick: () => this.removeMember(member)
    }) : null)));
  }

  /** Names as they're typed, a quarter second after the last key (needs the forum's user search). */
  search(value) {
    this.query(value);
    this.picked = null;
    this.alertAttrs = null;
    clearTimeout(this.searchTimer);
    if (!value.trim() || !app.forum.attribute('canSearchUsers')) {
      this.results = [];
      return;
    }
    this.searchTimer = setTimeout(() => {
      app.store.find('users', {
        filter: {
          q: value.trim()
        },
        page: {
          limit: 5
        }
      }).then(users => {
        if (this.query() !== value) return;
        this.results = users.filter(user => user !== this.attrs.build.user());
        m.redraw();
      });
    }, 250);
  }
  pick(user) {
    this.picked = user;
    this.results = [];
  }

  /** The picked member, one of the results whose name was typed in full, or a lookup by that name. */
  invitee() {
    const typed = this.query().trim().toLowerCase();
    const match = this.results.find(user => user.username().toLowerCase() === typed);
    if (this.picked || match) return Promise.resolve(this.picked || match);

    // A name nobody has gets our own message, not Flarum's "resource not found".
    return app.store.find('users', this.query().trim(), {
      bySlug: true
    }, {
      errorHandler: error => Promise.reject(error)
    });
  }
  onsubmit(e) {
    e.preventDefault();
    this.loading = true;
    // What the fields show, not the last input event: iOS can still be holding the last
    // typed letter (autocorrect) when Send is tapped.
    const field = id => (this.element.querySelector(`#${id}`)?.value ?? '').trim();
    this.role(field('garage-team-role'));
    if (!this.picked) this.query(field('garage-team-user'));
    this.invitee().then(user => app.store.createRecord('garage-members').save({
      role: this.role().trim() || null,
      relationships: {
        user,
        build: this.attrs.build
      }
    })).then(member => {
      this.members = [...(this.members || []), member];
      this.query('');
      this.role('');
      this.picked = null;
      this.alertAttrs = null;
    }).catch(error => {
      if (error.status === 404) {
        this.alertAttrs = {
          type: 'error',
          content: t('team.no_such_member', {
            username: this.query().trim()
          })
        };
      } else {
        this.onerror(error);
      }
    }).finally(() => {
      this.loading = false;
      m.redraw();
    });
  }
  saveRole(member, role) {
    member.save({
      role: role.trim() || null
    }).then(() => m.redraw());
  }
  removeMember(member) {
    member.delete().then(() => {
      this.members = (this.members || []).filter(other => other !== member);
      // The page's team list follows: a removed member leaves the build's relationship too.
      setTeam(this.attrs.build, this.attrs.build.team().filter(other => other !== member));
      m.redraw();
    });
  }
}
flarum.reg.add('ernestdefoe-garage', 'forum/components/TeamModal', TeamModal);